(2576, 'D.3.1', 'Students are given copies of and are knowledgeable of the philosophy, vision, mission, goals and core values of the institution and those of their respective program(s) and have accepted the responsibility of realizing those that are relevant to their studies.', 807, 'D.3', NULL, '2026-06-30 00:23:12', '2026-06-30 00:23:12'),
(2577, 'D.3.2', 'The students have accepted the responsibility of implementing the institutional core values all the time, as a relevant component of all their subjects/courses.', 807, 'D.3', NULL, '2026-06-30 00:23:12', '2026-06-30 00:23:12'),
(2578, 'D.3.3', 'Co-curricular activities of students and evaluation instruments are aligned with the institutional philosophy and program objectives and outcomes.', 807, 'D.3', NULL, '2026-06-30 00:23:12', '2026-06-30 00:23:12'),
(2579, 'E.1', 'The different sectors of the school demonstrate acceptance of the institutional philosophy, vision, mission, goals and educational objectives of the different academic programs as their own.', 811, NULL, NULL, '2026-06-30 00:23:12', '2026-06-30 00:23:12'),
