(2658, 'E.3.2', ' Brochures/catalogues, which contain the identified and logically arranged exit competencies or program/student learning outcomes, which are sourced from official issuances of regulatory agencies (e.g. CMO, DepEd Order, PRC/professional organization policies and standards, etc.)', 830, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2659, 'E.3.4', 'Syllabi, which consistently include the institutional mission and educational objectives of the program. The focus of each syllabus is highlighted in a matrix showing the logical flow from the subject/course objectives, to the program/student learning outcomes or exit competencies of students, to the outcomes assessment activities and evidence of the attainment of outcomes.', 830, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2660, 'A.5', 'this is anew requirments\n', 822, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2661, 'A.6', 'This is a new requirements for me', 822, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2662, 'F.1', 'The school has a policy on recruitment of faculty members.', 827, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2663, 'F.2', 'Faculty members teach courses along their fields of specialization.', 827, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2664, 'F.3', 'Deficiencies in graduate degrees of faculty members are compensated by other qualifications, such as ITE-related research, industry experience and/or IT certifications.', 827, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2665, 'F.4', 'Faculty members assigned in Practicum Courses/OJT have at least three years of teaching/industry experience along their specialized fields of study.', 827, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2666, 'F.5', 'Faculty members are engaged in extension services, such as (please check the appropriate box):', 827, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2667, 'F.6', 'Faculty members are engaged in extension services, such as (please check the appropriate box):', 827, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2668, 'F.6.1', 'Consultancy', 827, 'F.6', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2669, 'F.6.2', 'Industry lecture/training', 827, 'F.6', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2670, 'F.6.3', 'Collaborative research/project partnership', 827, 'F.6', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2671, 'F.6.4', 'Industry immersion', 827, 'F.6', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2672, 'F.6.5', 'Others', 827, 'F.6', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2673, 'G.1', 'Endeavor to implement the philosophy and objectives of the institution and the specific objectives of the program under survey.', 828, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2674, 'G.2', 'Enrich their lessons through additional readings and creative use of library resources and other instructional/learning resources.', 828, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2675, 'G.3', 'Show mastery of their subject matter and preparedness for their class.', 828, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2676, 'G.4', 'Are aware of recent educational/technological trends and problems and are able to relate the subject matter to current issues.', 828, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2677, 'G.5', 'Devote time to students for consultation, mentoring or academic advising outside of the classroom.', 828, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2678, 'H.1', 'A policy for determining teaching assignments and number of subject preparations is followed.', 831, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2679, 'H.2', 'The percentage of faculty members employed on full-time basis meets the accreditation standards, as follows:', 831, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2680, 'H.2.1', 'General education faculty members', 831, 'H.2', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2681, 'H.2.2', 'Faculty members handling the professional courses', 831, 'H.2', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2682, 'H.3', 'Faculty members are given teaching assignments only along their fields of specialization, as follows:', 831, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2683, 'H.3.1', 'C.3.1. General education faculty members', 831, 'H.3', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2684, 'H.3.2', 'Faculty members handling the professional courses', 831, 'H.3', NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2685, 'H.4', 'Teaching loads of faculty members (both full-time and part-time) allow sufficient time for preparation of classes, adequate evaluation of student achievement, and consultation, mentoring or academic advising.', 831, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2686, 'H.5', 'The quality of teaching performance is considered when assigning faculty load.', 831, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2687, 'H.6', 'Provision is made for the equitable distribution of co-curricular assignments of faculty members i.e., advisorship, membership, chairmanship, etc.', 831, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
(2688, 'I.1', 'The criteria for promotion in rank and remuneration include the following:', 832, NULL, NULL, '2026-06-30 14:27:49', '2026-06-30 14:27:49'),
